import attr

def test_pre_init_with_defaults():
    called_with = None

    @attr.s
    class C:
        x = attr.ib(default=42)

        def __attrs_pre_init__(self, x):
            nonlocal called_with
            called_with = x

    inst = C(x=100)
    assert called_with == 100

import attr

def test_pre_init_with_factory():
    called_with = None

    @attr.s
    class C:
        x = attr.ib(factory=list)

        def __attrs_pre_init__(self, x):
            nonlocal called_with
            called_with = x

    inst = C(x=[1, 2, 3])
    assert called_with == [1, 2, 3]

import attr


def test_pre_init_receives_provided_argument_when_field_has_default():
    received = None

    @attr.s
    class C:
        x = attr.ib(default=42)

        def __attrs_pre_init__(self, x):
            nonlocal received
            received = x

    C(x=100)
    assert received == 100

